DO $$
DECLARE
    v_user_id BIGINT;
    BEGIN
    INSERT INTO "user" (name, date_of_birth, password)
    VALUES ('Иван Иванов', '1990-05-15', 'password123')
        RETURNING id INTO v_user_id;

    INSERT INTO account (user_id, balance)
    VALUES (v_user_id, 1000.50);

    INSERT INTO email_data (user_id, email)
    VALUES (v_user_id, 'ivan.ivanov@example.com');

    INSERT INTO phone_data (user_id, phone)
    VALUES (v_user_id, '79207865432');
END $$;

